/** Map unchanged aggregate invoice lines explicitly to existing unpaid jobs. */
final class GE_Work_History_Consolidation {
    const ACTION='ge_finance_work_history_consolidate';
    private static function item_data($item){$d=$item->get_data();$d['meta_data']=array_map(static function($m){return $m->get_data();},$item->get_meta_data());return $d;}
    private static function evidence($o){$qid=absint($o->get_meta('_ge_commercial_quote_id',true));return array('documents'=>$o->get_meta(GE_WTP_Documents::META_KEY,true),'receipt_uploaded'=>$o->get_meta('_ge_payment_receipt_uploaded_at',true),'payment_state'=>$o->get_meta('_ge_payment_state',true),'manual_ledger'=>$o->get_meta(GE_Work_Finance::META,true),'balance_attempt'=>$o->get_meta('_ge_commercial_balance_payment_order',true),'initial_attempt'=>$qid?get_post_meta($qid,'_ge_commercial_initial_payment_order',true):'','pending_attempt'=>GE_Work_Finance::pending_attempt($o));}
    private static function state($order){
        $s=array('domain'=>GE_Work_Historical_Reconciliation::snapshot($order),'items'=>array(),'tax'=>(string)$order->get_total_tax(),'discount'=>(string)$order->get_discount_total(),'evidence'=>self::evidence($order),'children_items'=>array(),'children_evidence'=>array());
        foreach($order->get_items(array('line_item','fee','shipping','tax','coupon')) as $id=>$i){$i->read_meta_data(true);$s['items'][$id]=self::item_data($i);}ksort($s['items']);
        foreach(array_keys($s['domain']['children']??array()) as $id){$c=GE_Work_Finance::strict_order($id);$s['children_evidence'][$id]=self::evidence($c);foreach($c->get_items() as $iid=>$i){$i->read_meta_data(true);$s['children_items'][$id][$iid]=self::item_data($i);}if(isset($s['children_items'][$id]))ksort($s['children_items'][$id]);}ksort($s['children_items']);ksort($s['children_evidence']);GE_Work_History_Storage::check();return $s;
    }
    private static function digest($order){return hash('sha256',wp_json_encode(self::state($order)));}
    public static function plan($id,$map){
        if(!GE_Work_Historical_Reconciliation::allowed())throw new DomainException('Acceso denegado.');
        $o=GE_Work_Finance::strict_order($id);$o->read_meta_data(true);$source=GE_Work_Historical_Reconciliation::source($o);$qid=absint($o->get_meta('_ge_commercial_quote_id',true));
        if(!$source || !$qid || $o->meta_exists(GE_Work_History_Components::META))throw new DomainException('Revisá los vínculos actuales del agregado.');
        $r=$source['row'];$q=GE_WTP_Commercial_Quotes::get($qid,get_current_user_id());
        if(is_wp_error($q) || (int)$q['converted_order_id']!==$id || (int)$r['quote_id']!==$qid || $r['commercial']!=='performed' || $r['production']!=='completed' || $r['payment']!=='unpaid')throw new DomainException('Se requiere el presupuesto realizado, terminado y sin cobrar.');
        GE_Work_Historical_Reconciliation::plan($o,$source);$balance=GE_Work_Finance::balance($o);GE_Work_History_Storage::check();
        if(is_wp_error($balance) || $balance['amount_paid_cents']!==0 || $o->get_meta(GE_Work_Finance::META,true) || $o->get_date_paid() || $o->get_transaction_id() || GE_Work_Finance::pending_attempt($o) || $o->get_meta('_ge_financial_parent_order_id',true) || $o->get_items('fee') || $o->get_items('shipping') || $o->get_meta('_ge_payment_state',true)==='receipt_uploaded' || $o->get_meta('_ge_payment_receipt_uploaded_at',true))throw new DomainException('El agregado tiene movimientos que requieren revisión.');
        foreach(GE_WTP_Documents::get_documents($id) as $doc)if(in_array($doc['category']??'',array('comprobante','recibo'),true))throw new DomainException('Hay documentos de cobro pendientes.');GE_Work_History_Storage::check();
        $items=$o->get_items();$frozen=array_values($q['snapshot']['items']);if(!$items || count($items)!==count($frozen) || count($items)>100)throw new DomainException('Los renglones no coinciden con el presupuesto.');
        $clean=array();foreach((array)$map as $iid=>$cid){$iid=absint($iid);$cid=absint($cid);if(!$iid || !$cid || isset($clean[$iid]))throw new DomainException('Revisá la asignación de cada renglón.');$clean[$iid]=$cid;}ksort($clean);$item_ids=array_keys($items);sort($item_ids,SORT_NUMERIC);if(array_keys($clean)!==$item_ids)throw new DomainException('Asigná todos los renglones, una única vez.');
        $qty=0;$assigned=array();$representatives=array();$tags=array();$index=0;
        foreach($items as $iid=>$item){$line=$frozen[$index++];$item->read_meta_data(true);$n=(int)$item->get_quantity();if($n<=0 || (float)$n!==(float)$item->get_quantity() || (float)$line['quantity']!==(float)$n || $item->get_name()!==$line['name'] || GE_WTP_Quote_Balance::cents(wc_format_decimal($item->get_total(),2))!==(int)($line['taxable_base_cents']??$line['net_cents']) || GE_WTP_Quote_Balance::cents(wc_format_decimal($item->get_total_tax(),2))!==(int)($line['tax_cents']??0))throw new DomainException('Un renglón cambió respecto del presupuesto.');
            foreach(array('_ge_work_order_id','_ge_historical_component_order_id') as $key){if($item->meta_exists($key))throw new DomainException('Un renglón ya tiene referencias de producción.');$tags[$iid][$key]=array('exists'=>false,'value'=>'');}
            $cid=$clean[$iid];$assigned[$cid]=($assigned[$cid]??0)+$n;$qty+=$n;if(!isset($representatives[$cid]))$representatives[$cid]=$iid;
        }
        $ids=array_values(array_unique(array_values($clean)));sort($ids,SORT_NUMERIC);if(in_array($id,$ids,true))throw new DomainException('El agregado no puede incluirse como trabajo anterior.');
        // The accepted snapshot is untouched: this local copy reuses native validation only.
        $validation=$q;$base=$frozen[0];$base['quantity']=$qty;$validation['snapshot']['items']=array($base);$components=GE_Work_History_Components::prepare($validation,$ids);$component_cas=array();
        foreach($components as $cid=>$component){if(($assigned[$cid]??0)!==$component['quantity'])throw new DomainException('Las cantidades asignadas no coinciden con el trabajo anterior.');$component_cas[$cid]=self::state(GE_Work_Finance::strict_order($cid));}
        return array('order_id'=>$id,'quote_id'=>$qid,'ids'=>$ids,'map'=>$clean,'representatives'=>$representatives,'tags_before'=>$tags,'source'=>$source,'components'=>$components,'before'=>GE_Work_Historical_Reconciliation::snapshot($o),'before_state'=>self::state($o),'hash'=>hash('sha256',wp_json_encode(array(self::state($o),$component_cas,$clean,$source))));
    }
    public static function apply($preview){
        if(!GE_Work_Historical_Reconciliation::allowed())throw new DomainException('Acceso denegado.');$id=absint($preview['order_id']??0);$ids=array_map('absint',(array)($preview['ids']??array()));$locks=array();$touched=array_keys((array)($preview['map']??array()));$started=false;
        try{self::locks($id,$ids,$locks);GE_Work_History_Storage::begin($id,$ids,array(absint($preview['quote_id']??0)));$started=true;$p=self::plan($id,$preview['map']??array());if(!hash_equals($p['hash'],(string)($preview['hash']??'')))throw new DomainException('Cambió una ficha desde la revisión.');
            $o=GE_Work_Finance::strict_order($id);$o->read_meta_data(true);foreach($p['representatives'] as $cid=>$iid){$item=$o->get_item($iid);$item->update_meta_data('_ge_historical_component_order_id',$cid);$item->save_meta_data();GE_Work_History_Storage::check();}
            GE_Work_History_Components::attach($o,$p['components']);$proof=$o->get_meta(GE_Work_History_Components::META,true);$proof['existing_aggregate']=true;$proof['before_parent']=$p['before'];$proof['before_state']=$p['before_state'];$proof['item_map']=$p['map'];$proof['representatives']=$p['representatives'];$proof['tags_before']=$p['tags_before'];$proof['source_digest']=hash('sha256',wp_json_encode($p['source']));$o->update_meta_data(GE_Work_History_Components::META,$proof);GE_Work_History_Storage::save_order_meta($o);
            GE_Work_Finance::clear_item_cache($touched);GE_Work_Finance::clear_order_cache($id);$fresh=GE_Work_Finance::strict_order($id);$fresh->read_meta_data(true);$after=GE_Work_Historical_Reconciliation::snapshot($fresh);if(count($after['children'])!==count($ids) || $after['total']!==$p['before']['total'])throw new RuntimeException('No se verificaron todos los vínculos.');
            $proof['after_hash']=self::digest($fresh);$fresh->update_meta_data(GE_Work_History_Components::META,$proof);$audit=(array)$fresh->get_meta(GE_Work_Historical_Reconciliation::AUDIT,true);$audit[]=array('id'=>wp_generate_uuid4(),'operation'=>'consolidate','at'=>gmdate('c'),'actor'=>get_current_user_id(),'source_digest'=>$proof['source_digest'],'before'=>$p['before'],'after_hash'=>$proof['after_hash'],'component_ids'=>$ids);$fresh->update_meta_data(GE_Work_Historical_Reconciliation::AUDIT,$audit);GE_Work_History_Storage::save_order_meta($fresh);GE_Work_History_Storage::check();GE_Work_History_Storage::commit();$started=false;return $id;
        }catch(Throwable $e){if($started)GE_Work_History_Storage::abort();throw $e;}finally{self::clear($id,$ids,$touched,$locks);}
    }
    public static function rollback($id,$expected){
        if(!GE_Work_Historical_Reconciliation::allowed())throw new DomainException('Acceso denegado.');$o=GE_Work_Finance::strict_order($id);$o->read_meta_data(true);$proof=$o->get_meta(GE_Work_History_Components::META,true);$ids=array_map('absint',array_keys($proof['components']??array()));$touched=array_keys($proof['item_map']??array());$locks=array();$started=false;
        try{self::locks($id,$ids,$locks);GE_Work_History_Storage::begin($id,$ids,array(absint($o->get_meta('_ge_commercial_quote_id',true))));$started=true;$o=GE_Work_Finance::strict_order($id);$o->read_meta_data(true);$proof=$o->get_meta(GE_Work_History_Components::META,true);
            if(empty($proof['existing_aggregate']) || empty($proof['item_map']) || !hash_equals((string)($proof['after_hash']??''),(string)$expected) || !hash_equals((string)$proof['after_hash'],self::digest($o)) || array_keys($proof['item_map'])!==$touched || array_map('absint',array_keys($proof['components']))!==$ids)throw new DomainException('Hay cambios posteriores; no se restaurarán los vínculos.');
            $source=GE_Work_Historical_Reconciliation::source($o);if(!$source || !hash_equals($proof['source_digest'],hash('sha256',wp_json_encode($source))))throw new DomainException('Cambió la confirmación de origen.');$before=GE_Work_Historical_Reconciliation::snapshot($o);
            foreach($proof['representatives'] as $cid=>$iid){$item=$o->get_item($iid);if(!$item)throw new DomainException('Falta un renglón vinculado.');foreach($proof['tags_before'][$iid] as $key=>$m){if($m['exists'])$item->update_meta_data($key,$m['value']);else $item->delete_meta_data($key);}$item->save_meta_data();GE_Work_History_Storage::check();}
            foreach($proof['components'] as $cid=>$component){$child=GE_Work_Finance::strict_order($cid);$child->read_meta_data(true);foreach($component['before']['meta'] as $key=>$m){if($m['exists'])$child->update_meta_data($key,$m['value']);else $child->delete_meta_data($key);}GE_Work_History_Storage::save_order_meta($child);GE_Work_History_Storage::check();}
            $o->delete_meta_data(GE_Work_History_Components::META);GE_Work_History_Storage::save_order_meta($o);GE_Work_Finance::clear_item_cache($touched);GE_Work_Finance::clear_order_cache($id);$fresh=GE_Work_Finance::strict_order($id);$fresh->read_meta_data(true);if(self::state($fresh)!==$proof['before_state'])throw new RuntimeException('No se verificó la restauración exacta.');
            $audit=(array)$fresh->get_meta(GE_Work_Historical_Reconciliation::AUDIT,true);$audit[]=array('id'=>wp_generate_uuid4(),'operation'=>'consolidation_rollback','at'=>gmdate('c'),'actor'=>get_current_user_id(),'before'=>$before,'after_hash'=>GE_Work_Historical_Reconciliation::hash(GE_Work_Historical_Reconciliation::snapshot($fresh)));$fresh->update_meta_data(GE_Work_Historical_Reconciliation::AUDIT,$audit);GE_Work_History_Storage::save_order_meta($fresh);GE_Work_History_Storage::check();GE_Work_History_Storage::commit();$started=false;return $id;
        }catch(Throwable $e){if($started)GE_Work_History_Storage::abort();throw $e;}finally{self::clear($id,$ids,$touched,$locks);}
    }
    private static function locks($id,$ids,&$locks){$all=array_values(array_unique(array_merge(array($id),$ids)));sort($all,SORT_NUMERIC);foreach($all as $oid){$o=GE_Work_Finance::strict_order($oid);$key=GE_Work_Finance::collection_lock($o);if(in_array($key,$locks,true))continue;if(!GE_Work_Finance::lock($key))throw new DomainException('Un trabajo está siendo procesado.');$locks[]=$key;}}
    private static function clear($id,$ids,$items,$locks){GE_Work_Finance::clear_item_cache($items);foreach(array_merge(array($id),$ids) as $oid)GE_Work_Finance::clear_order_cache($oid);foreach(array_reverse($locks) as $key)GE_Work_Finance::unlock($key);}
    public static function render($o){
        if(!GE_Work_Historical_Reconciliation::allowed())return;$proof=$o->get_meta(GE_Work_History_Components::META,true);$rollback=$proof && !empty($proof['existing_aggregate']) && !empty($proof['after_hash']) && hash_equals($proof['after_hash'],self::digest($o));if($proof && !$rollback)return;
        $source=GE_Work_Historical_Reconciliation::source($o);$qid=absint($o->get_meta('_ge_commercial_quote_id',true));if(!$source || !$qid || $source['row']['production']!=='completed' || $source['row']['payment']!=='unpaid')return;
        $token=sanitize_text_field(wp_unslash($_GET['component_review']??''));$preview=preg_match('/^[a-f0-9-]{36}$/D',$token)?get_transient('ge_component_review_'.get_current_user_id().'_'.$token):null;
        echo '<details><summary>'.($rollback?'Vínculos del agregado aplicados':'Vincular trabajos anteriores a este agregado').'</summary><form class="ge-admin-form" method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="'.self::ACTION.'"><input type="hidden" name="order_id" value="'.$o->get_id().'">';wp_nonce_field(self::ACTION.'_'.$o->get_id());
        if($rollback){echo '<input type="hidden" name="operation" value="rollback"><input type="hidden" name="expected_hash" value="'.esc_attr($proof['after_hash']).'"><label><input type="checkbox" name="confirmed" value="1" required> Restaurar exclusivamente los vínculos anteriores.</label><button>Restaurar vínculos anteriores</button>';}
        elseif($preview && (int)$preview['order_id']===$o->get_id()){echo '<input type="hidden" name="review_token" value="'.esc_attr($token).'"><p>Trabajos incluidos: '.esc_html(implode(', ',$preview['ids'])).'. Se conservan todos los renglones, importes e IVA de la única venta.</p><ul>';foreach($preview['map'] as $iid=>$cid){$item=$o->get_item($iid);echo '<li>'.esc_html($item?$item->get_name():'Renglón').' → #'.absint($cid).'</li>';}echo '</ul><label><input type="checkbox" name="confirmed" value="1" required> Confirmo esta asignación de todos los renglones.</label><button>Aplicar vínculos revisados</button>';}
        else{$options=array();foreach(wc_get_orders(array('customer_id'=>$o->get_customer_id(),'limit'=>100,'orderby'=>'ID','order'=>'DESC')) as $candidate){if($candidate->get_id()===$o->get_id() || $candidate->get_meta('_ge_work_order',true)==='yes' || $candidate->get_meta('_ge_financial_parent_order_id',true) || $candidate->get_meta('_ge_commercial_payment_order',true)==='yes' || in_array($candidate->get_status(),array('cancelled','failed','refunded'),true) || $candidate->get_date_paid() || $candidate->get_meta(GE_Work_Finance::META,true) || $candidate->get_meta(GE_Work_Finance::HISTORICAL_META,true))continue;$b=GE_Work_Finance::balance($candidate);if(is_wp_error($b)||$b['amount_paid_cents'])continue;$options[$candidate->get_id()]='#'.$candidate->get_order_number();}echo '<p>Asigná cada renglón al trabajo anterior correspondiente. No se cambiarán productos, cantidades, precios ni impuestos.</p>';foreach($o->get_items() as $iid=>$item){echo '<label>'.esc_html($item->get_name()).'<select name="component_map['.absint($iid).']" required><option value="">Elegir trabajo anterior</option>';foreach($options as $cid=>$label)echo '<option value="'.absint($cid).'">'.esc_html($label).'</option>';echo '</select></label>';}echo '<button>Revisar vínculos del agregado</button>';}
        echo '</form></details>';
    }
    public static function handle(){
        if(!GE_Work_Historical_Reconciliation::allowed())GE_Work_Historical_Reconciliation::deny();$id=absint($_POST['order_id']??0);check_admin_referer(self::ACTION.'_'.$id);
        try{if(($_POST['operation']??'')==='rollback'){if(empty($_POST['confirmed']))throw new DomainException('Confirmá la restauración.');self::rollback($id,sanitize_text_field($_POST['expected_hash']??''));$args=array('section'=>'orders','order_id'=>$id);}else{$token=sanitize_text_field($_POST['review_token']??'');if($token){$key='ge_component_review_'.get_current_user_id().'_'.$token;$p=get_transient($key);if(!$p || (int)$p['order_id']!==$id || empty($_POST['confirmed']))throw new DomainException('Revisá nuevamente la asignación.');self::apply($p);delete_transient($key);$args=array('section'=>'orders','order_id'=>$id);}else{$p=self::plan($id,(array)($_POST['component_map']??array()));$token=wp_generate_uuid4();set_transient('ge_component_review_'.get_current_user_id().'_'.$token,$p,15*MINUTE_IN_SECONDS);$args=array('section'=>'orders','order_id'=>$id,'component_review'=>$token);}}}
        catch(Throwable $e){wp_die(esc_html($e->getMessage()),'',array('response'=>409));}wp_safe_redirect(add_query_arg($args,home_url('/gestion/')));exit;
    }
}
add_action('admin_post_'.GE_Work_History_Consolidation::ACTION,array('GE_Work_History_Consolidation','handle'));
add_action('admin_post_nopriv_'.GE_Work_History_Consolidation::ACTION,array('GE_Work_Historical_Reconciliation','deny'));
